use crate::standards::v1::subsets::mesh::schema::snapshot::{SemioMeshSnapshot,SemioMesh,SemioPrimitive,SemioTopology,SemioMaterial,SemioTexture};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(crate) fn encode(snapshot:&SemioMeshSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{native_encoding::encode(encoding,"semio stdio.semio.mesh.dsl v1\n","stdio.semio.mesh.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn point(point:&SemioPoint3,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.number(point.x,encoding)?;writer.delimiter(b",",encoding)?;writer.number(point.y,encoding)?;writer.delimiter(b",",encoding)?;writer.number(point.z,encoding)?;writer.delimiter(b"]",encoding)}
fn uv(uv:&SemioUv,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.number(uv.u,encoding)?;writer.delimiter(b",",encoding)?;writer.number(uv.v,encoding)?;writer.delimiter(b"]",encoding)}
fn rgba(color:&SemioRgba,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;for(index,value)in [color.r,color.g,color.b,color.a].into_iter().enumerate(){if index!=0{writer.delimiter(b",",encoding)?;}writer.number32(value,encoding)?;}writer.delimiter(b"]",encoding)}
fn primitive(primitive:&SemioPrimitive,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{
 writer.delimiter(b"[",encoding)?;writer.string(&primitive.id,encoding)?;writer.delimiter(b",",encoding)?;writer.byte(match (&primitive.topology,encoding){(SemioTopology::Points,SnapshotEncoding::Binary)=>0,(SemioTopology::Lines,SnapshotEncoding::Binary)=>1,(SemioTopology::LineStrip,SnapshotEncoding::Binary)=>2,(SemioTopology::Triangles,SnapshotEncoding::Binary)=>3,(SemioTopology::TriangleStrip,SnapshotEncoding::Binary)=>4,(SemioTopology::TriangleFan,SnapshotEncoding::Binary)=>5,(SemioTopology::Points,SnapshotEncoding::Text)=>b'P',(SemioTopology::Lines,SnapshotEncoding::Text)=>b'L',(SemioTopology::LineStrip,SnapshotEncoding::Text)=>b'S',(SemioTopology::Triangles,SnapshotEncoding::Text)=>b'T',(SemioTopology::TriangleStrip,SnapshotEncoding::Text)=>b'X',(SemioTopology::TriangleFan,SnapshotEncoding::Text)=>b'F'})?;
 writer.delimiter(b",",encoding)?;writer.list(&primitive.positions,encoding,|writer,value|point(value,writer,encoding))?;writer.delimiter(b",",encoding)?;writer.list(&primitive.normals,encoding,|writer,value|point(value,writer,encoding))?;writer.delimiter(b",",encoding)?;writer.list(&primitive.uvs,encoding,|writer,value|uv(value,writer,encoding))?;writer.delimiter(b",",encoding)?;writer.list(&primitive.colors,encoding,|writer,value|rgba(value,writer,encoding))?;writer.delimiter(b",",encoding)?;writer.list(&primitive.indices,encoding,|writer,value|writer.fixed_u32(*value,encoding))?;writer.delimiter(b",",encoding)?;
 match &primitive.material_id{Some(id)=>{if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"[1,")?}writer.string(id,encoding)?;writer.delimiter(b"]",encoding)?},None=>if encoding==SnapshotEncoding::Binary{writer.byte(0)?}else{writer.bytes(b"[0]")?}}writer.delimiter(b"]",encoding)
}
fn mesh(mesh:&SemioMesh,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&mesh.id,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&mesh.primitives,encoding,|writer,value|primitive(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
fn optional_text(value:&Option<String>,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{match value{Some(id)=>{if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"[1,")?}writer.string(id,encoding)?;writer.delimiter(b"]",encoding)},None=>if encoding==SnapshotEncoding::Binary{writer.byte(0)}else{writer.bytes(b"[0]")}}}
fn material(material:&SemioMaterial,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&material.id,encoding)?;writer.delimiter(b",",encoding)?;rgba(&material.base_color,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.number32(material.metallic,encoding)?;writer.delimiter(b",",encoding)?;writer.number32(material.roughness,encoding)?;for value in [&material.base_color_texture, &material.metallic_roughness_texture, &material.normal_texture, &material.occlusion_texture, &material.emissive_texture]{writer.delimiter(b",",encoding)?;optional_text(value,writer,encoding)?;}writer.delimiter(b"]",encoding)}
fn texture(texture:&SemioTexture,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&texture.id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&texture.mime,encoding)?;writer.delimiter(b",",encoding)?;writer.octets(&texture.bytes,encoding)?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioMeshSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"schema=")?}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nmeshes=",encoding)?;writer.list(&snapshot.meshes,encoding,|writer,value|mesh(value,writer,encoding))?;writer.delimiter(b"\nmaterials=",encoding)?;writer.list(&snapshot.materials,encoding,|writer,value|material(value,writer,encoding))?;writer.delimiter(b"\ntextures=",encoding)?;writer.list(&snapshot.textures,encoding,|writer,value|texture(value,writer,encoding))}

